import sys

def evaluate(expr: str) -> int:
    # Increase recursion limit for deeply nested expressions
    sys.setrecursionlimit(1000000)

    # Tokenize
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c <= ' ':
            i += 1
        elif c.isdigit():
            j = i + 1
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
        elif c in '+-*/()':
            tokens.append(('OP', c))
            i += 1
        else:
            raise ValueError(f"Unexpected character: {c!r}")

    pos = 0
    tok_len = len(tokens)

    def parse_expr():
        # Expression: Term (('+' | '-') Term)*
        val = parse_term()
        while pos < tok_len:
            t = tokens[pos]
            if t[0] == 'OP' and t[1] in ('+', '-'):
                op = t[1]
                pos += 1
                rhs = parse_term()
                if op == '+':
                    val += rhs
                else:
                    val -= rhs
            else:
                break
        return val

    def parse_term():
        # Term: Unary (('*' | '/') Unary)*
        val = parse_unary()
        while pos < tok_len:
            t = tokens[pos]
            if t[0] == 'OP' and t[1] in ('*', '/'):
                op = t[1]
                pos += 1
                rhs = parse_unary()
                if op == '*':
                    val *= rhs
                else:
                    # Integer division truncating toward zero
                    q = abs(val) // abs(rhs)
                    if (val < 0) ^ (rhs < 0):
                        val = -q
                    else:
                        val = q
            else:
                break
        return val

    def parse_unary():
        # Unary: ('+' | '-')* Primary
        sign = 1
        while pos < tok_len:
            t = tokens[pos]
            if t[0] == 'OP' and t[1] in ('+', '-'):
                op = t[1]
                pos += 1
                if op == '-':
                    sign = -sign
                # '+' does nothing to sign
            else:
                break
        val = parse_primary()
        return sign * val

    def parse_primary():
        # Primary: Number | '(' Expression ')'
        t = tokens[pos]
        if t[0] == 'NUM':
            pos += 1
            return t[1]
        elif t[1] == '(':
            pos += 1
            val = parse_expr()
            # Expect ')'
            if pos < tok_len and tokens[pos][1] == ')':
                pos += 1
            return val
        else:
            raise ValueError(f"Unexpected token: {t}")

    result = parse_expr()
    return result
