import heapq
from collections import defaultdict


def alien_order(words: list[str]) -> str:
    # Collect all distinct letters
    letters = set()
    for word in words:
        for ch in word:
            letters.add(ch)

    if not letters:
        return ""

    # Build graph and compute in-degrees
    graph = {ch: set() for ch in letters}
    in_degree = {ch: 0 for ch in letters}

    # Extract constraints from adjacent word pairs
    for i in range(len(words) - 1):
        w1, w2 = words[i], words[i + 1]
        min_len = min(len(w1), len(w2))
        found_diff = False
        for j in range(min_len):
            if w1[j] != w2[j]:
                if w2[j] not in graph[w1[j]]:
                    graph[w1[j]].add(w2[j])
                    in_degree[w2[j]] += 1
                found_diff = True
                break
        # If no differing character found, w1 must not be longer than w2
        if not found_diff and len(w1) > len(w2):
            return ""

    # Topological sort using a min-heap to get lexicographically smallest order
    heap = [ch for ch in letters if in_degree[ch] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        ch = heapq.heappop(heap)
        result.append(ch)
        for neighbor in graph[ch]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    # Cycle detection: if not all letters were placed, there's a cycle
    if len(result) != len(letters):
        return ""

    return ''.join(result)
